{
  "appearance_facts": [
    {
      "location": "chart, x-axis, left-to-right",
      "fact": "Four stacked bars are labeled Tue, Wed, Thu, and Mon; each bar is a vertical stack of a blue base, a green middle, and an orange top."
    },
    {
      "location": "chart, y-axis",
      "fact": "The vertical axis runs from about 1,000 at the bottom to 4,500 near the top, with labeled ticks at 1,000, 1,500, 2,000, 2,500, 3,000, 3,500, and 4,500."
    },
    {
      "location": "chart, Tue bar",
      "fact": "The Tue stack top is the highest on the page, slightly above the 4,500 tick; its blue segment ends near 1,300 and the green segment ends near 3,300."
    },
    {
      "location": "chart, Wed bar",
      "fact": "The Wed stack top is just above the 4,500 tick; its blue segment ends near 1,350 and the green segment ends near 2,650."
    },
    {
      "location": "chart, Thu bar",
      "fact": "The Thu stack top is between the 4,000 and 4,500 ticks, around 4,150; its blue segment ends near 1,100 and the green segment ends near 2,650."
    },
    {
      "location": "chart, Mon bar",
      "fact": "The Mon stack top is just below the 4,000 tick, around 3,900; its blue segment ends near 1,350 and the green segment ends near 2,800."
    },
    {
      "location": "legend, upper right",
      "fact": "The legend shows blue for Station X, green for Station Y, and orange for Station Z."
    }
  ],
  "printed_facts": [
    {
      "location": "title",
      "fact": "Title reads 'Visitors at Three Train Stations in City Z'."
    },
    {
      "location": "y-axis label",
      "fact": "Y-axis is labeled 'Number of Visitors'."
    },
    {
      "location": "x-axis label",
      "fact": "X-axis is labeled 'Date' with category labels Tue, Wed, Thu, Mon."
    },
    {
      "location": "legend",
      "fact": "Legend entries are Station X (blue), Station Y (green), Station Z (orange)."
    },
    {
      "location": "y-axis ticks",
      "fact": "Visible numeric ticks include 1,000, 1,500, 2,000, 2,500, 3,000, 3,500, and 4,500."
    },
    {
      "location": "policy table",
      "fact": "Crowding alert request rule: combined visitors across Station X, Station Y, and Station Z exceed 4,500 for a day."
    }
  ],
  "public_definitions": [
    "Crowding alert request: Combined visitors across Station X, Station Y, and Station Z exceed 4,500 for a day."
  ],
  "uncertain": [
    "Exact combined totals are not labeled on the bars; values are estimated from the stacked bar heights against the y-axis ticks.",
    "The Wed total appears just above 4,500, so whether it strictly exceeds 4,500 depends on precise reading of the bar top."
  ]
}
